/* @lc app=leetcode id=2025 lang=kotlin */ class Solution { fun waysToPartition(nums: IntArray, k: Int): Int = nums.size.let { n -> nums.runningFold(0L) { s, x -> s + x }.let { pre -> (1 until n).map { 2 * pre[it] - pre[n] }.let { diff -> HashMap<Long, Int>().also { r -> diff.forEach { r.merge(it, 1) { a, b -> a + b } } }.let { right -> HashMap<Long, Int>().let { left -> maxOf(diff.count { it == 0L }, (0 until n).maxOf { j -> (if (j >= 1) diff[j - 1].let { v -> right.merge(v, -1) { a, b -> a + b }.also { left.merge(v, 1) { a, b -> a + b } } } else null).let { (k - nums[j]).toLong().let { dl -> (left[dl] ?: 0) + (right[-dl] ?: 0) } } }) } } } } } }